      maxScore: 50,
      questions: [
        QuizQuestion(id: 'q2_1_1', question: Bi('What is the primary purpose of government sector organizations?', 'ما هو الغرض الرئيسي للمنظمات الحكومية؟'), options: [Bi('Maximize profits for shareholders', 'تعظيم الأرباح للمساهمين'), Bi('Serve public interest and provide essential services', 'خدمة المصلحة العامة وتقديم الخدمات الأساسية'), Bi('Compete with private businesses', 'التنافس مع الشركات الخاصة'), Bi('Generate returns for investors', 'توليد عوائد للمستثمرين')], correctIndex: 1, explanation: Bi('Government exists to serve the public interest, providing essential services like healthcare, education, infrastructure, and security regardless of profitability.', 'توجد الحكومة لخدمة المصلحة العامة، وتوفير الخدمات الأساسية مثل الرعاية الصحية والتعليم والبنية التحتية والأمن بغض النظر عن الربحية.')),
        QuizQuestion(id: 'q2_1_4', question: Bi('Which type of transactions are unique to government revenue?', 'أي نوع من المعاملات فريد لإيرادات الحكومة؟'), options: [Bi('Product sales to customers', 'مبيعات المنتجات للعملاء'), Bi('Non-exchange transactions like taxes and grants', 'المعاملات غير التبادلية مثل الضرائب والمنح'), Bi('Service fees at market rates', 'رسوم الخدمة بأسعار السوق'), Bi('Stock dividends', 'أرباح الأسهم')], correctIndex: 1, explanation: Bi('Non-exchange transactions (where no direct service is received in return) like taxes and grants are unique to government and require special accounting treatment.', 'المعاملات غير التبادلية (حيث لا يتم الحصول على خدمة مباشرة في المقابل) مثل الضرائب والمنح فريدة للحكومة وتتطلب معالجة محاسبية خاصة.')),
        QuizQuestion(id: 'q2_1_8', question: Bi('What is the key difference between government and private sector revenue sources?', 'ما الفرق الرئيسي بين مصادر إيرادات الحكومة والقطاع الخاص؟'), options: [Bi('Government revenues are always larger', 'الإيرادات الحكومية دائمًا أكبر'), Bi('Government relies on non-voluntary sources (taxes); private sector on voluntary market transactions', 'تعتمد الحكومة على مصادر غير طوعية (الضرائب)؛ القطاع الخاص على معاملات السوق الطوعية'), Bi('Private sector only uses equity financing', 'القطاع الخاص يستخدم فقط تمويل الأسهم'), Bi('No significant difference exists', 'لا يوجد فرق كبير')], correctIndex: 1, explanation: Bi('Government revenues are largely non-voluntary (taxes, fees mandated by law) while private sector revenues come from voluntary market transactions where customers choose to buy products/services.', 'إيرادات الحكومة غير طوعية إلى حد كبير (الضرائب والرسوم المفروضة بالقانون) بينما تأتي إيرادات القطاع الخاص من معاملات السوق الطوعية حيث يختار العملاء شراء المنتجات/الخدمات.')),
        QuizQuestion(id: 'q2_1_10', question: Bi('Which accountability mechanism is unique to government?', 'أي آلية مساءلة فريدة للحكومة؟'), options: [Bi('Shareholder voting at annual meetings', 'تصويت المساهمين في الاجتماعات السنوية'), Bi('Legislative oversight and public audits', 'الرقابة التشريعية والتدقيق العام'), Bi('Stock market performance monitoring', 'مراقبة أداء سوق الأسهم'), Bi('Board of directors approval', 'موافقة مجلس الإدارة')], correctIndex: 1, explanation: Bi('Government faces legislative oversight (parliament/congress), public audits by independent auditors, freedom of information requirements, and electoral accountability - mechanisms unique to the public sector.', 'تواجه الحكومة الرقابة التشريعية (البرلمان/الكونجرس) والتدقيق العام من قبل المدققين المستقلين ومتطلبات حرية المعلومات والمساءلة الانتخابية - آليات فريدة للقطاع العام.')),
        QuizQuestion(id: 'q2_1_13', question: Bi('What does IPSAS stand for and what is its purpose?', 'ما الذي يرمز إليه IPSAS وما هو الغرض منه؟'), options: [Bi('International Private Sector Accounting Standards - for corporations', 'معايير المحاسبة الدولية للقطاع الخاص - للشركات'), Bi('International Public Sector Accounting Standards - for government entities', 'معايير المحاسبة الدولية للقطاع العام - للجهات الحكومية'), Bi('Internal Planning and Strategic Systems - for budgeting', 'أنظمة التخطيط والاستراتيجية الداخلية - للميزانية'), Bi('Integrated Performance and Service Standards - for quality', 'معايير الأداء والخدمة المتكاملة - للجودة')], correctIndex: 1, explanation: Bi('IPSAS (International Public Sector Accounting Standards) are designed specifically for government and public sector entities to ensure accountability, transparency, and comparability in financial reporting.', 'IPSAS (معايير المحاسبة الدولية للقطاع العام) مصممة خصيصًا للجهات الحكومية والقطاع العام لضمان المساءلة والشفافية والقابلية للمقارنة في التقارير المالية.')),
        QuizQuestion(id: 'q2_1_15', question: Bi('Why does IPSAS use "net assets/equity" instead of "shareholder equity"?', 'لماذا تستخدم IPSAS "صافي الأصول/حقوق الملكية" بدلاً من "حقوق ملكية المساهمين"؟'), options: [Bi('To make calculations easier', 'لتسهيل الحسابات'), Bi('Because government entities have no owners in the traditional sense', 'لأن الجهات الحكومية ليس لها ملاك بالمعنى التقليدي'), Bi('IPSAS and IFRS use identical terminology', 'تستخدم IPSAS و IFRS مصطلحات متطابقة'), Bi('To comply with tax regulations', 'للامتثال للأنظمة الضريبية')], correctIndex: 1, explanation: Bi('Government entities are owned by citizens collectively, not shareholders. IPSAS uses "net assets/equity" to reflect this fundamental difference - the government is a steward of public resources, not owned by investors.', 'الجهات الحكومية مملوكة من قبل المواطنين بشكل جماعي، وليس من قبل المساهمين. تستخدم IPSAS "صافي الأصول/حقوق الملكية" لتعكس هذا الاختلاف الأساسي - الحكومة هي مشرف على الموارد العامة، وليست مملوكة من قبل المستثمرين.')),
        QuizQuestion(id: 'q2_1_19', question: Bi('In the Saudi context, which entities use IFRS vs IPSAS?', 'في السياق السعودي، ما الجهات التي تستخدم IFRS مقابل IPSAS؟'), options: [Bi('All entities use IFRS only', 'جميع الجهات تستخدم IFRS فقط'), Bi('Listed companies on Tadawul use IFRS; government ministries and agencies use IPSAS', 'الشركات المدرجة في تداول تستخدم IFRS؛ الوزارات والوكالات الحكومية تستخدم IPSAS'), Bi('All entities use IPSAS only', 'جميع الجهات تستخدم IPSAS فقط'), Bi('Saudi Arabia does not follow international standards', 'السعودية لا تتبع المعايير الدولية')], correctIndex: 1, explanation: Bi('Saudi Arabia adopted IFRS for private companies listed on Tadawul stock exchange and IPSAS for government entities as part of Vision 2030 financial reforms to improve transparency and comparability.', 'اعتمدت السعودية IFRS للشركات الخاصة المدرجة في سوق تداول للأوراق المالية و IPSAS للجهات الحكومية كجزء من إصلاحات رؤية 2030 المالية لتحسين الشفافية والقابلية للمقارنة.')),
        QuizQuestion(id: 'q2_2_1', question: Bi('How does government budgeting differ from private sector budgeting?', 'كيف تختلف الميزانية الحكومية عن ميزانية القطاع الخاص؟'), options: [Bi('No significant difference exists', 'لا يوجد فرق كبير'), Bi('Government budgets require legislative approval; private budgets are internal management tools', 'تتطلب الميزانيات الحكومية موافقة تشريعية؛ الميزانيات الخاصة هي أدوات إدارية داخلية'), Bi('Private sector budgets are legally binding; government budgets are flexible', 'ميزانيات القطاع الخاص ملزمة قانونًا؛ الميزانيات الحكومية مرنة'), Bi('Both types of budgets are identical', 'كلا النوعين من الميزانيات متطابقان')], correctIndex: 1, explanation: Bi('Government budgets must be approved by legislature (parliament/congress) and are legally binding appropriations. Private sector budgets are internal management tools that can be modified by executives without external approval.', 'يجب أن توافق السلطة التشريعية (البرلمان/الكونجرس) على الميزانيات الحكومية وهي اعتمادات ملزمة قانونًا. ميزانيات القطاع الخاص هي أدوات إدارية داخلية يمكن للمديرين التنفيذيين تعديلها دون موافقة خارجية.')),
        QuizQuestion(id: 'q2_2_5', question: Bi('What is "value for money" in government performance measurement?', 'ما هي "القيمة مقابل المال" في قياس الأداء الحكومي؟'), options: [Bi('Achieving maximum profits', 'تحقيق أقصى قدر من الأرباح'), Bi('Achieving best outcomes with efficient use of public resources', 'تحقيق أفضل النتائج مع الاستخدام الفعال للموارد العامة'), Bi('Spending the entire budget allocation', 'إنفاق كامل تخصيص الميزانية'), Bi('Maximizing tax collections', 'تعظيم تحصيل الضرائب')], correctIndex: 1, explanation: Bi('Value for money measures whether government achieves the best outcomes (effectiveness) with efficient use of resources (efficiency) - getting maximum public benefit per dollar spent.', 'تقيس القيمة مقابل المال ما إذا كانت الحكومة تحقق أفضل النتائج (الفعالية) مع الاستخدام الفعال للموارد (الكفاءة) - الحصول على أقصى فائدة عامة لكل دولار يُنفق.')),
        QuizQuestion(id: 'q2_2_8', question: Bi('How does government measure efficiency versus effectiveness?', 'كيف تقيس الحكومة الكفاءة مقابل الفعالية؟'), options: [Bi('Efficiency = cost per output; Effectiveness = achievement of desired outcomes', 'الكفاءة = التكلفة لكل مخرج؛ الفعالية = تحقيق النتائج المرجوة'), Bi('Both measure the same thing', 'كلاهما يقيس نفس الشيء'), Bi('Efficiency = profit; Effectiveness = revenue', 'الكفاءة = الربح؛ الفعالية = الإيرادات'), Bi('Only efficiency matters in government', 'فقط الكفاءة مهمة في الحكومة')], correctIndex: 0, explanation: Bi('Efficiency measures cost per output (e.g., cost per student educated). Effectiveness measures whether desired outcomes were achieved (e.g., improved literacy rates). Government needs both metrics.', 'تقيس الكفاءة التكلفة لكل مخرج (على سبيل المثال، تكلفة كل طالب متعلم). تقيس الفعالية ما إذا تم تحقيق النتائج المرجوة (على سبيل المثال، تحسين معدلات محو الأمية). الحكومة تحتاج كلا المقياسين.')),
        QuizQuestion(id: 'q2_2_9', question: Bi('Why is government risk tolerance generally more conservative?', 'لماذا يكون تحمل المخاطر الحكومية عمومًا أكثر تحفظًا؟'), options: [Bi('Government has unlimited resources', 'الحكومة لديها موارد غير محدودة'), Bi('Government is steward of public funds and failures damage public trust', 'الحكومة هي مشرف على الأموال العامة والإخفاقات تضر بالثقة العامة'), Bi('Government cannot borrow money', 'الحكومة لا يمكنها اقتراض المال'), Bi('Private sector has zero risk tolerance', 'القطاع الخاص لديه تحمل صفر للمخاطر')], correctIndex: 1, explanation: Bi('Government manages taxpayer money and must be conservative because failures can damage public trust, have political consequences, and affect essential services. Private sector can take higher risks with investor capital.', 'تدير الحكومة أموال دافعي الضرائب ويجب أن تكون محافظة لأن الإخفاقات يمكن أن تضر بالثقة العامة وتكون لها عواقب سياسية وتؤثر على الخدمات الأساسية. يمكن للقطاع الخاص تحمل مخاطر أعلى برأس مال المستثمرين.')),
        QuizQuestion(id: 'q2_2_12', question: Bi('Why does government face greater transparency requirements?', 'لماذا تواجه الحكومة متطلبات شفافية أكبر؟'), options: [Bi('Government operations are funded by taxpayers who have a right to information', 'العمليات الحكومية ممولة من دافعي الضرائب الذين لهم الحق في المعلومات'), Bi('Government has no transparency requirements', 'الحكومة ليس لديها متطلبات شفافية'), Bi('Private sector has higher transparency requirements', 'القطاع الخاص لديه متطلبات شفافية أعلى'), Bi('Transparency only applies to defense spending', 'الشفافية تنطبق فقط على الإنفاق الدفاعي')], correctIndex: 0, explanation: Bi('Government is funded by taxpayer money, creating a fundamental right to information. Citizens must be able to monitor how public funds are used, driving requirements for budget disclosure, financial reporting, and public audits.', 'الحكومة ممولة من أموال دافعي الضرائب، مما يخلق حقًا أساسيًا في المعلومات. يجب أن يكون المواطنون قادرين على مراقبة كيفية استخدام الأموال العامة، مما يدفع متطلبات الإفصاح عن الميزانية والتقارير المالية والتدقيق العام.')),
        QuizQuestion(id: 'q2_2_13', question: Bi('A government agency spent 95% of its budget but achieved only 60% of service targets. How should this be evaluated?', 'أنفقت وكالة حكومية 95٪ من ميزانيتها لكنها حققت فقط 60٪ من أهداف الخدمة. كيف ينبغي تقييم هذا؟'), options: [Bi('Excellent performance - high budget execution', 'أداء ممتاز - تنفيذ ميزانية عالي'), Bi('Poor performance - low effectiveness despite spending', 'أداء ضعيف - فعالية منخفضة على الرغم من الإنفاق'), Bi('Average performance - some money left over', 'أداء متوسط - بقي بعض المال'), Bi('Cannot evaluate without profit data', 'لا يمكن التقييم بدون بيانات الربح')], correctIndex: 1, explanation: Bi('This shows poor effectiveness - high spending but low achievement of service targets. Government performance should focus on outcomes achieved, not just budget execution. This indicates inefficiency or poor program design.', 'هذا يظهر فعالية ضعيفة - إنفاق عالي ولكن تحقيق منخفض لأهداف الخدمة. يجب أن يركز أداء الحكومة على النتائج المحققة، وليس فقط تنفيذ الميزانية. يشير هذا إلى عدم الكفاءة أو تصميم البرنامج السيئ.')),
        QuizQuestion(id: 'q2_2_14', question: Bi('Why might a private company deliberately underspend its budget while a government agency would not?', 'لماذا قد تقلل شركة خاصة عن قصد من الإنفاق من ميزانيتها بينما لن تفعل وكالة حكومية ذلك؟'), options: [Bi('Private companies maximize profit by controlling costs; government agencies may lose unspent appropriations', 'الشركات الخاصة تعظم الربح بالتحكم في التكاليف؛ الوكالات الحكومية قد تفقد الاعتمادات غير المنفقة'), Bi('Government agencies always have surplus funds', 'الوكالات الحكومية دائمًا لديها أموال فائضة'), Bi('Private companies cannot control spending', 'الشركات الخاصة لا يمكنها التحكم في الإنفاق'), Bi('There is no difference in behavior', 'لا يوجد فرق في السلوك')], correctIndex: 0, explanation: Bi('Private companies benefit from saving money (higher profits). Government agencies often face "use it or lose it" appropriations - unspent funds may be lost and future budgets reduced, creating perverse incentive to spend entire allocation.', 'تستفيد الشركات الخاصة من توفير المال (أرباح أعلى). غالبًا ما تواجه الوكالات الحكومية اعتمادات "استخدمها أو اخسرها" - قد تُفقد الأموال غير المنفقة وتُخفض الميزانيات المستقبلية، مما يخلق حافزًا سلبيًا لإنفاق كامل التخصيص.')),
        QuizQuestion(id: 'q2_3_2', question: Bi('What type of audit is unique to government entities?', 'ما نوع التدقيق الفريد للجهات الحكومية؟'), options: [Bi('Financial statement audit only', 'تدقيق البيانات المالية فقط'), Bi('Performance audit examining efficiency and effectiveness of programs', 'تدقيق الأداء الذي يفحص كفاءة وفعالية البرامج'), Bi('Inventory count audits', 'تدقيق جرد المخزون'), Bi('Marketing effectiveness audits', 'تدقيق فعالية التسويق')], correctIndex: 1, explanation: Bi('Government undergoes performance audits examining whether programs achieve objectives efficiently and effectively. Private sector focuses mainly on financial statement audits to verify accuracy of financial reporting.', 'تخضع الحكومة لتدقيق الأداء الذي يفحص ما إذا كانت البرامج تحقق الأهداف بكفاءة وفعالية. يركز القطاع الخاص بشكل رئيسي على تدقيق البيانات المالية للتحقق من دقة التقارير المالية.')),
        QuizQuestion(id: 'q2_3_3', question: Bi('How does government HR management differ from private sector?', 'كيف تختلف إدارة الموارد البشرية الحكومية عن القطاع الخاص؟'), options: [Bi('No significant differences exist', 'لا توجد اختلافات كبيرة'), Bi('Government follows civil service rules with greater job security; private sector has more flexibility', 'الحكومة تتبع قواعد الخدمة المدنية مع أمان وظيفي أكبر؛ القطاع الخاص لديه مرونة أكبر'), Bi('Private sector offers more job security', 'القطاع الخاص يوفر أمانًا وظيفيًا أكبر'), Bi('Government can hire and fire at will', 'الحكومة يمكنها التوظيف والفصل حسب الرغبة')], correctIndex: 1, explanation: Bi('Government employees typically work under civil service systems with standardized pay scales, greater job security, defined benefit pensions, but less flexibility in hiring/firing. Private sector has more flexibility in compensation and employment decisions.', 'عادةً ما يعمل موظفو الحكومة تحت أنظمة الخدمة المدنية مع جداول رواتب موحدة وأمان وظيفي أكبر ومعاشات محددة الاستحقاق، ولكن مرونة أقل في التوظيف/الفصل. القطاع الخاص لديه مرونة أكبر في التعويضات وقرارات التوظيف.')),
        QuizQuestion(id: 'q2_3_6', question: Bi('How does Saudi Vision 2030 exemplify government-private sector partnership?', 'كيف تجسد رؤية السعودية 2030 الشراكة بين الحكومة والقطاع الخاص؟'), options: [Bi('Government eliminates all private sector involvement', 'الحكومة تلغي جميع مشاركات القطاع الخاص'), Bi('Government sets strategic direction while enabling private sector growth and foreign investment', 'الحكومة تحدد الاتجاه الاستراتيجي بينما تمكن نمو القطاع الخاص والاستثمار الأجنبي'), Bi('Private sector controls all government decisions', 'القطاع الخاص يتحكم في جميع القرارات الحكومية'), Bi('No partnership exists', 'لا توجد شراكة')], correctIndex: 1, explanation: Bi('Vision 2030 demonstrates government setting strategic national priorities (economic diversification, non-oil revenue, tourism, technology) while creating enabling environment for private sector investment, entrepreneurship, and foreign participation.', 'تظهر رؤية 2030 الحكومة تحدد الأولويات الوطنية الاستراتيجية (التنويع الاقتصادي، الإيرادات غير النفطية، السياحة، التكنولوجيا) بينما تخلق بيئة تمكينية لاستثمار القطاع الخاص وريادة الأعمال والمشاركة الأجنبية.')),
        QuizQuestion(id: 'q2_3_7', question: Bi('What role does Saudi Aramco play in bridging government and commercial objectives?', 'ما الدور الذي تلعبه أرامكو السعودية في سد الفجوة بين الأهداف الحكومية والتجارية؟'), options: [Bi('Aramco operates purely as private company ignoring national interests', 'أرامكو تعمل فقط كشركة خاصة تتجاهل المصالح الوطنية'), Bi('Aramco is government-controlled but listed on Tadawul, balancing national energy security with shareholder returns', 'أرامكو تحت السيطرة الحكومية لكنها مدرجة في تداول، توازن بين أمن الطاقة الوطني وعوائد المساهمين'), Bi('Aramco has no connection to government', 'أرامكو ليس لها علاقة بالحكومة'), Bi('Aramco only focuses on profit maximization', 'أرامكو تركز فقط على تعظيم الربح')], correctIndex: 1, explanation: Bi('Saudi Aramco is unique: government-controlled (national oil company) but partially listed on Tadawul stock exchange. It must balance national objectives (energy security, economic development) with commercial performance and shareholder returns - exemplifying hybrid model.', 'أرامكو السعودية فريدة: تحت السيطرة الحكومية (شركة النفط الوطنية) لكنها مدرجة جزئيًا في سوق تداول. يجب أن توازن بين الأهداف الوطنية (أمن الطاقة، التنمية الاقتصادية) والأداء التجاري وعوائد المساهمين - مما يجسد النموذج الهجين.')),
        QuizQuestion(id: 'q2_3_10', question: Bi('How do Public-Private Partnerships (PPPs) combine both sector strengths?', 'كيف تجمع الشراكات بين القطاعين العام والخاص (PPP) نقاط القوة في كلا القطاعين؟'), options: [Bi('PPPs eliminate government involvement completely', 'الشراكات بين القطاعين تلغي مشاركة الحكومة تمامًا'), Bi('Government provides regulatory framework and public interest focus; private sector provides capital and operational efficiency', 'الحكومة توفر الإطار التنظيمي والتركيز على المصلحة العامة؛ القطاع الخاص يوفر رأس المال والكفاءة التشغيلية'), Bi('Private sector sets all regulations', 'القطاع الخاص يضع جميع اللوائح'), Bi('PPPs only work in healthcare', 'الشراكات بين القطاعين تعمل فقط في الرعاية الصحية')], correctIndex: 1, explanation: Bi('PPPs leverage government\'s regulatory authority, public service mandate, and land/resources with private sector\'s capital, management expertise, innovation, and efficiency. Examples: toll roads, hospitals, airports, utilities.', 'تستفيد الشراكات بين القطاعين من سلطة الحكومة التنظيمية وتفويض الخدمة العامة والأراضي/الموارد مع رأس المال والخبرة الإدارية والابتكار والكفاءة للقطاع الخاص. أمثلة: الطرق ذات الرسوم، المستشفيات، المطارات، المرافق.')),
        QuizQuestion(id: 'q2_3_14', question: Bi('What is "intergenerational equity" and why does it matter more to government?', 'ما هي "العدالة بين الأجيال" ولماذا تهم الحكومة أكثر؟'), options: [Bi('Equal pay across all age groups', 'أجور متساوية عبر جميع الفئات العمرية'), Bi('Ensuring future generations are not burdened by current decisions on debt, environment, and resources', 'ضمان عدم تحمل الأجيال المستقبلية أعباء القرارات الحالية بشأن الديون والبيئة والموارد'), Bi('Corporate succession planning', 'تخطيط التعاقب المؤسسي'), Bi('Hiring practices for young workers', 'ممارسات التوظيف للعمال الشباب')], correctIndex: 1, explanation: Bi('Intergenerational equity means current government decisions (debt levels, environmental policies, resource depletion, infrastructure investment) should not unfairly burden future generations. Government has responsibility across generations; private sector focuses on current shareholders.', 'تعني العدالة بين الأجيال أن قرارات الحكومة الحالية (مستويات الديون، السياسات البيئية، استنزاف الموارد، الاستثمار في البنية التحتية) يجب ألا تثقل كاهل الأجيال المستقبلية بشكل غير عادل. الحكومة لديها مسؤولية عبر الأجيال؛ القطاع الخاص يركز على المساهمين الحاليين.')),
